static void describe_engine()
{
  std::string cfg = VSIM_CPU_PYMODULE_NAME;  // "simulator_<cfg>"
  const std::string prefix = "simulator_";
  if (cfg.starts_with(prefix))
    cfg = cfg.substr(prefix.size());

  const std::string_view blob(&_binary_config_inc_start,
                              static_cast<size_t>(&_binary_config_inc_end
                                                  - &_binary_config_inc_start));
  auto scan_int = [blob](std::string_view key) -> long {
    size_t pos = blob.find(key);
    if (pos == std::string_view::npos)
      return 0;
    pos += key.size();
    while (pos < blob.size() && (blob[pos] < '0' || blob[pos] > '9'))
      ++pos;
    long v = 0;
    while (pos < blob.size() && blob[pos] >= '0' && blob[pos] <= '9')
      v = v * 10 + (blob[pos++] - '0');
    return v;
  };
  const long vlen = scan_int("NDS_VLEN");
  const long dlen = scan_int("NDS_DLEN");
  const long elen = scan_int("NDS_ELEN");
  const long xlen = scan_int("NDS_XLEN");

  // Built by hand (not fmt) to keep the literal {bin}/{elf}/{state_in}
  // placeholders out of fmt's brace parser.
  std::string json;
  json += "{\n";
  json += "  \"id\": \"verilator:" + cfg + "\",\n";
  json += "  \"type\": \"verilator\",\n";
  json += "  \"kind\": \"cycle-accurate\",\n";
  json += "  \"vlen\": " + std::to_string(vlen) + ", \"dlen\": "
          + std::to_string(dlen) + ", \"elen\": " + std::to_string(elen)
          + ", \"xlen\": " + std::to_string(xlen) + ",\n";
  json += "  \"triggers\": [\"csr\", \"pc\"],\n";
  json += "  \"roles\": [\"standalone\", \"accurate-leg\"],\n";
  json += "  \"state\": [\"resume\", \"drain\"],\n";
  // Andes custom CSRs this core actually implements (from its config.inc).
  // The driver uses this to skip --verify on CSRs the engine lacks, mirroring
  // the resume/drain gating in ResumeDriver/StateDrain (single binder).
  const std::vector<std::string> andes_csrs =
      hybrid::supported_andes_csr_names(hybrid::andes_caps_from_config());
  json += "  \"andes_csrs\": [";
  for (size_t i = 0; i < andes_csrs.size(); ++i)
    json += (i ? ", \"" : "\"") + andes_csrs[i] + "\"";
  json += "],\n";
  json += "  \"invoke\": {\n";
  json += "    \"standalone\": [\"{bin}\", \"{elf}\"],\n";
  json += "    \"accurate-leg\": [\"{bin}\", \"{elf}\", "
          "\"--resume-from-qemu\", \"{state_in}\", "
          "\"--handoff-out\", \"{state_out}\", "
          "\"--shared-mem-path\", \"{mmap}\", "
          "\"--shared-mem-size\", \"{mmap_size}\", "
          "\"--shared-mem-base\", \"{mmap_base}\"]\n";
  json += "  },\n";
  json += "  \"result\": \"stderr:cycles\"\n";
  json += "}\n";
  fwrite(json.data(), 1, json.size(), stdout);
}

