    // The Andes PMNDS counter block (SPA existence: mmsc_cfg.PMNDS, plus
    // misa[20] or misa[18] for the U/S members). mcountermask_m (0x7D1) is a
    // v3 Andes CSR; its siblings share the gate. Over-claiming any of these
    // faults the abstract csrr with cmderr=3 -- seen live for 0x7D1 on premium
    // (M-only) and 0x7CF on advanced (Sscofpmf replaces PMNDS).
    case 0x7CF: return AndesGate::PMNDS;          // mcounterinten
    case 0x7CE: case 0x7D1: case 0x7D3:           // mcounterwen, mcountermask_m/_u
      return AndesGate::PMNDS_UMODE;
    case 0x7D2: return AndesGate::PMNDS_SMODE;    // mcountermask_s
    // umisc_ctl: "Access Mode: User and above" is WHO may touch it, not an
    // existence condition -- spec existence is ALT_FP_FMT | CST_CTL (RTL:
    // BFLOAT16_ARITH | ACE, no privilege term).
    case 0x813: return AndesGate::ALT_FP;
    // The STANDARD counters exist under either perf-monitor scheme (Zihpm);
    // only the Andes PMNDS block above is scheme-dependent.
    case 0x320: case 0xB03: case 0xB04: case 0xB05: case 0xB06:  // mcountinhibit, mhpmcounter3-6
    case 0x323: case 0x324: case 0x325: case 0x326:              // mhpmevent3-6
      return AndesGate::PERF_MONITOR;
    // mnvec is base Andes NMI state -- spec "IM Requirement: Required", RTL
    // decodes it unconditionally even on cores that lack Smrnmi. So it is
    // ALWAYS, not gated on the resumable-NMI extension.
    case 0x7C3:                                   // mnvec
    case 0x7C9: return AndesGate::ALWAYS;         // mdcause (base Andes trap CSR)
    default:
      // PMA cfg (0xBC0, 0xBC2) and addr (0xBD0..0xBDF) blocks.
      if (csr_addr == HYBRID_PMA_CFG0_CSR || csr_addr == HYBRID_PMA_CFG0_CSR + 2)
        return AndesGate::PMA;
      if (csr_addr >= HYBRID_PMA_ADDR0_CSR &&
          csr_addr < HYBRID_PMA_ADDR0_CSR + HYBRID_PMA_ADDR_NUM)
        return AndesGate::PMA;
      return AndesGate::ALWAYS;                    // mxstatus 0x7C4, mclk_ctl 0x7DF
  }
}

// The set of Andes feature gates a target core has on. Built from the core's
// compiled-in config (config.inc) in the sim binary and injected into the
// resume/drain loops, so they transport only the CSRs the core implements.
// Default = every gate on (all(): no gating, the prior unconditional behavior).
struct AndesCaps {
  uint32_t gate_mask = ~0u;

  static constexpr AndesCaps all()  { return AndesCaps{~0u}; }
  static constexpr AndesCaps none() { return AndesCaps{0u}; }

  constexpr void set(AndesGate g, bool on = true)
  {
    const uint32_t bit = 1u << static_cast<unsigned>(g);
    if (on) gate_mask |= bit;
    else    gate_mask &= ~bit;
  }

  constexpr bool gate_on(AndesGate g) const
  {
    return (gate_mask >> static_cast<unsigned>(g)) & 1u;
  }

  // ALWAYS-gated CSRs are present on every core regardless of the mask.
  constexpr bool supports_csr(uint16_t csr_addr) const
  {
    const AndesGate g = andes_gate_for(csr_addr);
    return g == AndesGate::ALWAYS || gate_on(g);
  }
};

// F6: build the caps from the CSR addresses the registered manifest transports,
// instead of from config macros (andes_caps_from_config). The transported set is
// a union of COMPLETE gate-groups -- supports_csr() keys on the gate, so every
// CSR sharing a gate transports together -- hence setting each transported CSR's
// gate reconstructs the EXACT caps. This lets the runtime be driven by the
// measured/registered manifest, making the config->caps model (the andesim
// mirror + parity guard) redundant. Verilator-free, so it stays unit-testable.
inline AndesCaps andes_caps_from_transport_set(const std::vector<uint16_t>& transported)
{
  AndesCaps c = AndesCaps::none();
  for (const uint16_t addr : transported)
    c.set(andes_gate_for(addr), true);
  return c;
}

// The gated CSR names this core supports, for the --describe card. Iterates the
// single-source-of-truth X-macro list of v3 Andes custom CSRs (plus PMA group
// markers). The driver uses this list to gate --verify, so a CSR the core lacks
// is neither restored, drained, nor compared. The v4 M-ext CSRs join at their
// later commit.
inline std::vector<std::string> supported_andes_csr_names(const AndesCaps& caps)
{
  std::vector<std::string> out;
#define X(field, addr, name) if (caps.supports_csr(addr)) out.push_back(name);
  HYBRID_ANDES_CSR_LIST(X)
#undef X
  // PMA group markers (whole pmacfg[]/pmaaddr[] blocks share one gate), so a
  // consumer can include/exclude PMA without listing all 18 entries.
  if (caps.supports_csr(HYBRID_PMA_CFG0_CSR))  out.push_back("pmacfg");
  if (caps.supports_csr(HYBRID_PMA_ADDR0_CSR)) out.push_back("pmaaddr");
  return out;
}

}  // namespace hybrid

#endif  // ANDES_HYBRID_ANDES_CAPS_HPP

// Build an AndesCaps from the core's compiled-in config.inc feature macros
// (_NDS_*, supplied by the build-generated cpu_config.hpp). This is the ONE
// place that binds each Andes feature gate to its config macro -- the sim-binary
// counterpart of the Verilator-free andes_caps.hpp, kept separate so the unit
// tests never need the generated header.
//
// PRECONDITION: the _NDS_* macros must already be in scope (include this AFTER
// cpu_config.hpp). A macro that is absent reads as "feature off" (gate clear),
// never a compile error -- so a core whose config omits a knob stays safe.
#pragma once

#include "hybrid/andes_caps.hpp"

namespace hybrid {

inline AndesCaps andes_caps_from_config()
{
  AndesCaps c = AndesCaps::none();

#if defined(_NDS_DSP_SUPPORT_INT) && _NDS_DSP_SUPPORT_INT
  c.set(AndesGate::DSP);           // ucode
#endif
#if defined(_NDS_CODENSE_SUPPORT_INT) && _NDS_CODENSE_SUPPORT_INT
  c.set(AndesGate::CODENSE);       // uitb
#endif
  // Zcmt (jvt): the RTL gates jvt on ZCE_SUPPORT_INT (kv_csr_dec.v); newer
  // config.inc generations carry NDS_ZCE_SUPPORT_INT (advanced: 0), older
  // ones (premium) have no knob at all -- absent reads as "feature off".
#if (defined(_NDS_ZCMT_SUPPORT_INT) && _NDS_ZCMT_SUPPORT_INT) || \
    (defined(_NDS_ZCE_SUPPORT_INT) && _NDS_ZCE_SUPPORT_INT)
  c.set(AndesGate::ZCMT);          // jvt
#endif
#if defined(_NDS_POWERBRAKE_SUPPORT_INT) && _NDS_POWERBRAKE_SUPPORT_INT
  c.set(AndesGate::POWERBRAKE);    // mpft_ctl
#endif
#if defined(_NDS_STACKSAFE_SUPPORT_INT) && _NDS_STACKSAFE_SUPPORT_INT
  c.set(AndesGate::STACKSAFE);     // mhsp_ctl, msp_bound, msp_base
#endif
#if defined(_NDS_PERFORMANCE_MONITOR_INT) && _NDS_PERFORMANCE_MONITOR_INT
  c.set(AndesGate::PERF_MONITOR);  // mcountinhibit, mhpmcounter/event3-6
  // Andes PMNDS scheme (mcounterinten, mcounterwen, mcountermask_*): exists
  // only when the standard Sscofpmf scheme does NOT replace it (RTL:
  // PERFORMANCE_MONITOR_INT==1 & SSCOFPMF_SUPPORT==0), plus the privilege
  // term the SPA conditions carry.
#if !defined(_NDS_SSCOFPMF_SUPPORT) || !_NDS_SSCOFPMF_SUPPORT
  c.set(AndesGate::PMNDS);
#if defined(_NDS_NUM_PRIVILEGE_LEVELS) && (_NDS_NUM_PRIVILEGE_LEVELS >= 2)
  c.set(AndesGate::PMNDS_UMODE);
#endif
#if defined(_NDS_NUM_PRIVILEGE_LEVELS) && (_NDS_NUM_PRIVILEGE_LEVELS >= 3)
  c.set(AndesGate::PMNDS_SMODE);
#endif
#endif
#endif
#if defined(_NDS_PMA_ENTRIES) && (_NDS_PMA_ENTRIES > 0)
  c.set(AndesGate::PMA);           // pmacfg / pmaaddr
#endif
#if defined(_NDS_ILM_SIZE_KB) && (_NDS_ILM_SIZE_KB > 0)
  c.set(AndesGate::ILM);           // milmb
#endif
#if defined(_NDS_DLM_SIZE_KB) && (_NDS_DLM_SIZE_KB > 0)
  c.set(AndesGate::DLM);           // mdlmb
#endif
  // ECC: mecc_code exists if ANY RAM block is configured with ECC.
#if (defined(_NDS_DCACHE_ECC_TYPE_INT) && _NDS_DCACHE_ECC_TYPE_INT) || \
    (defined(_NDS_ICACHE_ECC_TYPE_INT) && _NDS_ICACHE_ECC_TYPE_INT) || \
    (defined(_NDS_ILM_ECC_TYPE_INT)    && _NDS_ILM_ECC_TYPE_INT)    || \
    (defined(_NDS_DLM_ECC_TYPE_INT)    && _NDS_DLM_ECC_TYPE_INT)
  c.set(AndesGate::ECC);           // mecc_code
#endif
  // umisc_ctl existence: BF16 arithmetic or ACE (spec ALT_FP_FMT | CST_CTL).
  // "Access Mode: User and above" is who may touch it, not an existence term.
#if (defined(_NDS_BFLOAT16_ARITH_SUPPORT) && _NDS_BFLOAT16_ARITH_SUPPORT) || \
    (defined(_NDS_ACE_SUPPORT_INT) && _NDS_ACE_SUPPORT_INT)
  c.set(AndesGate::ALT_FP);        // umisc_ctl
#endif

  return c;
}

}  // namespace hybrid

// Andes-CSR capability gating. A core implements only the Andes CSRs its
// config.inc enables; restoring a CSR the core lacks can hang the DMI
// handshake (observed on ax45mpv_premium: ucode + mecc_code). So the
// resume/drain loops transport only the CSRs the target core supports. This
// pins the CSR-address -> feature-gate map and the premium subset.
#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include "doctest.h"

#include "hybrid/andes_caps.hpp"
#include "hybrid/state_abi.h"

#include <algorithm>
#include <string>
#include <vector>

using hybrid::AndesCaps;
using hybrid::AndesGate;

// ax45mpv_premium config.inc: CoDense + ILM + DLM + perf monitor on
// (NDS_PERFORMANCE_MONITOR_INT=1); NDS_SSCOFPMF_SUPPORT=0 so the Andes PMNDS
// counter scheme is live (PMNDS gate on); DSP, ECC, PowerBrake, StackSafe,
// PMA off; M-only (NDS_NUM_PRIVILEGE_LEVELS=1 -> PMNDS_UMODE off).
static AndesCaps premium()
{
  AndesCaps c = AndesCaps::none();
  c.set(AndesGate::CODENSE);
  c.set(AndesGate::ILM);
  c.set(AndesGate::DLM);
  c.set(AndesGate::PERF_MONITOR);
  c.set(AndesGate::PMNDS);
  c.set(AndesGate::ALT_FP);  // NDS_BFLOAT16_ARITH_SUPPORT=1 + ACE
  return c;
}

// ax46mpv_advanced config.inc: perf monitor on BUT NDS_SSCOFPMF_SUPPORT=1 --
// the standard Sscofpmf scheme replaces the Andes PMNDS counter CSRs, so the
// PMNDS gates stay off. CoDense + ILM + DLM + PMA on; M-only.
static AndesCaps advanced()
{
  AndesCaps c = AndesCaps::none();
  c.set(AndesGate::CODENSE);
  c.set(AndesGate::ILM);
  c.set(AndesGate::DLM);
  c.set(AndesGate::PERF_MONITOR);
  c.set(AndesGate::PMA);
  c.set(AndesGate::ALT_FP);  // BF16 arith + ACE
  return c;
}

TEST_CASE("registration audit: the two v3 under-claim classes are gated right")
{
  // Found by the ax46mpv_advanced registration audit (both engines'
  // kv_csr_dec.v existent_csr agree with the SPA):
  // 1. mnvec 0x7C3: spec "IM Requirement: Required", RTL unconditional --
  //    it is base Andes NMI state, NOT part of Smrnmi (0x740-0x744, which
  //    these cores genuinely lack).
  CHECK(AndesCaps::none().supports_csr(0x7C3));   // ALWAYS
  // 2. umisc_ctl 0x813: spec ALT_FP_FMT|CST_CTL, RTL BF16_ARITH|ACE --
  //    "Access Mode: User and above" is who may TOUCH it, not an existence
  //    condition; a core without BF16/ACE does not implement it.
  CHECK(premium().supports_csr(0x813));
  CHECK(advanced().supports_csr(0x813));
  CHECK_FALSE(AndesCaps::none().supports_csr(0x813));  // no BF16/ACE: absent
}

TEST_CASE("all() transports every Andes CSR (default = no gating)")
{
  const AndesCaps c = AndesCaps::all();
  CHECK(c.supports_csr(0x801));  // ucode
  CHECK(c.supports_csr(0x7C2));  // mecc_code
  CHECK(c.supports_csr(0x800));  // uitb
}

TEST_CASE("premium skips the CSRs its config lacks -- no hang")
{
  const AndesCaps c = premium();
  CHECK_FALSE(c.supports_csr(0x801));  // ucode      (DSP off)  -- the hang case
  CHECK_FALSE(c.supports_csr(0x7C2));  // mecc_code  (ECC off)  -- the hang case
  CHECK_FALSE(c.supports_csr(0x7C5));  // mpft_ctl   (PowerBrake off)
  CHECK_FALSE(c.supports_csr(0x7C6));  // mhsp_ctl   (StackSafe off)
  CHECK_FALSE(c.supports_csr(0x7C7));  // msp_bound
  CHECK_FALSE(c.supports_csr(0x7C8));  // msp_base
  CHECK_FALSE(c.supports_csr(0x7D1));  // mcountermask_m (M-only: needs U-mode)
  CHECK_FALSE(c.supports_csr(HYBRID_PMA_ADDR0_CSR));  // pmaaddr0 (PMA off)
  CHECK_FALSE(c.supports_csr(HYBRID_PMA_CFG0_CSR));   // pmacfg0
}

TEST_CASE("the PMNDS counter block needs the Andes scheme, not just a perf "
          "monitor: Sscofpmf cores drop it")
{
  // RTL ground truth (kv_csr_dec.v existent_csr): the PMNDS counter CSRs
  // exist iff PERFORMANCE_MONITOR_INT==1 & SSCOFPMF_SUPPORT==0 (+ privilege
  // terms) -- the standard Sscofpmf scheme REPLACES them. This is what the
  // SPA's `mmsc_cfg.PMNDS` condition compiles down to. ax46mpv_advanced
  // (perf monitor on, sscofpmf on) faulted the drain sweep on a csrr of
  // mcounterinten 0x7CF when it was gated on PERF_MONITOR alone.
  CHECK(premium().supports_csr(0x7CF));         // PMNDS scheme -> exists
  CHECK_FALSE(advanced().supports_csr(0x7CF));  // Sscofpmf -> replaced
  // The standard counters stay PERF_MONITOR-gated on both schemes.
  CHECK(advanced().supports_csr(0x320));        // mcountinhibit
  CHECK(advanced().supports_csr(0xB03));        // mhpmcounter3
}

TEST_CASE("mcountermask_m (0x7D1) needs PMNDS AND U-mode (PMNDS_UMODE)")
{
  // SPA IM Requirement: (mmsc_cfg.PMNDS==1) & (misa[20]==1) -- the same rule
  // as its twins mcountermask_u (0x7D3) and mcounterwen (0x7CE). RTL:
  // PERF & !SSCOFPMF & multi_level_mode. An M-only core (premium) or an
  // Sscofpmf core (advanced) does not implement them; a PB csrr raises
  // cmderr=3, which aborts a whole CSR sweep.
  CHECK_FALSE(premium().supports_csr(0x7D1));   // PMNDS but M-only
  CHECK_FALSE(advanced().supports_csr(0x7D1));  // U-mode-less AND no PMNDS

  AndesCaps pmnds_u = premium();
  pmnds_u.set(AndesGate::PMNDS_UMODE);
  CHECK(pmnds_u.supports_csr(0x7D1));
  CHECK(pmnds_u.supports_csr(0x7CE));           // mcounterwen: same rule
  CHECK(pmnds_u.supports_csr(0x7D3));           // mcountermask_u: same rule
  // mcountermask_s additionally needs S-mode.
  CHECK_FALSE(pmnds_u.supports_csr(0x7D2));
}

TEST_CASE("jvt (0x017) needs Zcmt, not CoDense")
{
  // jvt is the standard Zcmt table-jump base. Classic Andes CoDense is
  // exec.it + uitb (0x800); a CoDense core without Zcmt does not implement
  // jvt, and its csrr faulted the drain sweep on ax45mpv_premium. No
  // current engine config carries a Zcmt knob, so the gate reads as off.
  AndesCaps codense_only = AndesCaps::none();
  codense_only.set(AndesGate::CODENSE);
  CHECK(codense_only.supports_csr(0x800));       // uitb rides CoDense
  CHECK_FALSE(codense_only.supports_csr(0x017)); // jvt does not

  AndesCaps with_zcmt = codense_only;
  with_zcmt.set(AndesGate::ZCMT);
  CHECK(with_zcmt.supports_csr(0x017));
}

TEST_CASE("premium keeps the CSRs its config has")
{
  const AndesCaps c = premium();
  CHECK(c.supports_csr(0x800));  // uitb     (CoDense on)
  CHECK_FALSE(c.supports_csr(0x017));  // jvt: Zcmt, which premium lacks
  CHECK(c.supports_csr(0x7C0));  // milmb    (ILM on)
  CHECK(c.supports_csr(0x7C1));  // mdlmb    (DLM on)
  CHECK(c.supports_csr(0x7C4));  // mxstatus (base machine CSR -> ALWAYS)
  CHECK(c.supports_csr(0x7DF));  // mclk_ctl (base machine CSR -> ALWAYS)
}

TEST_CASE("--describe name list reflects the caps")
{
  const std::vector<std::string> n = hybrid::supported_andes_csr_names(premium());
  auto has = [&](const char* s) {
    return std::find(n.begin(), n.end(), s) != n.end();
  };
  CHECK(has("uitb"));
  CHECK(has("milmb"));
  CHECK_FALSE(has("ucode"));
  CHECK_FALSE(has("mecc_code"));

  // PMA group markers ("pmacfg"/"pmaaddr") are emitted only when PMA is on, so
  // the driver can verify-exclude the whole PMA block on a core that lacks it.
  CHECK_FALSE(has("pmacfg"));   // premium: PMA off
  CHECK_FALSE(has("pmaaddr"));
  const std::vector<std::string> all = hybrid::supported_andes_csr_names(AndesCaps::all());
  auto all_has = [&](const char* s) {
    return std::find(all.begin(), all.end(), s) != all.end();
  };
  CHECK(all_has("pmacfg"));
  CHECK(all_has("pmaaddr"));
}

TEST_CASE("F6: andes_caps_from_transport_set rebuilds caps from the transported set")
{
  // The runtime can be driven by the registered manifest instead of config
  // macros: the transported set is a union of complete gate-groups, so setting
  // each transported CSR's gate reconstructs the EXACT caps. Proven to match the
  // config-shape helpers for both built engines -- so config -> caps (from_config)
  // and manifest -> caps (from_transport_set) are interchangeable.
  for (const AndesCaps want : {premium(), advanced()}) {
    std::vector<uint16_t> transported;
    for (int a = 0; a <= 0xFFF; ++a) {
      const auto addr = static_cast<uint16_t>(a);
      if (want.supports_csr(addr)
          && hybrid::andes_gate_for(addr) != AndesGate::ALWAYS)
        transported.push_back(addr);
    }
    const AndesCaps rebuilt = hybrid::andes_caps_from_transport_set(transported);
    bool identical = true;
    for (int a = 0; a <= 0xFFF; ++a) {
      const auto addr = static_cast<uint16_t>(a);
      if (rebuilt.supports_csr(addr) != want.supports_csr(addr)) identical = false;
    }
    CHECK(identical);
  }
}

// Tests the config.inc-macro -> AndesCaps binding (andes_caps_from_config).
// The real _NDS_* macros come from the build-generated cpu_config.hpp; here we
// define them ourselves with ax45mpv_premium's values, so the #if mapping is
// unit-tested with controlled inputs and no Verilator build is needed.
//
// premium config.inc: CoDense + ILM + DLM on; DSP/ECC/PowerBrake/StackSafe/
// perf-monitor/PMA off.
#define _NDS_DSP_SUPPORT_INT         0
#define _NDS_CODENSE_SUPPORT_INT     1
#define _NDS_POWERBRAKE_SUPPORT_INT  0
#define _NDS_STACKSAFE_SUPPORT_INT   0
#define _NDS_PERFORMANCE_MONITOR_INT 0
#define _NDS_PMA_ENTRIES             0
#define _NDS_ILM_SIZE_KB             1024
#define _NDS_DLM_SIZE_KB             1024
#define _NDS_DCACHE_ECC_TYPE_INT     0
#define _NDS_ICACHE_ECC_TYPE_INT     0
#define _NDS_ILM_ECC_TYPE_INT        0
#define _NDS_DLM_ECC_TYPE_INT        0

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include "doctest.h"

#include "hybrid/andes_caps_config.hpp"

using hybrid::AndesGate;

TEST_CASE("premium config.inc macros -> CoDense + ILM + DLM gates only")
{
  const auto c = hybrid::andes_caps_from_config();

  CHECK(c.gate_on(AndesGate::CODENSE));
  CHECK(c.gate_on(AndesGate::ILM));
  CHECK(c.gate_on(AndesGate::DLM));

  CHECK_FALSE(c.gate_on(AndesGate::DSP));
  CHECK_FALSE(c.gate_on(AndesGate::ECC));
  CHECK_FALSE(c.gate_on(AndesGate::POWERBRAKE));
  CHECK_FALSE(c.gate_on(AndesGate::STACKSAFE));
  CHECK_FALSE(c.gate_on(AndesGate::PMA));
  CHECK_FALSE(c.gate_on(AndesGate::PERF_MONITOR));
}

TEST_CASE("the binding reaches the right CSR-level conclusion for premium")
{
  const auto c = hybrid::andes_caps_from_config();
  CHECK_FALSE(c.supports_csr(0x801));  // ucode    (DSP off)  -- the hang case
  CHECK_FALSE(c.supports_csr(0x7C2));  // mecc_code (ECC off) -- the hang case
  CHECK(c.supports_csr(0x800));        // uitb     (CoDense on)
  CHECK(c.supports_csr(0x7C0));        // milmb    (ILM on)
  CHECK(c.supports_csr(0x7C4));        // mxstatus (always)
}

